# Scan Logic
# ------------------------------------------------------------
class PCI_DEVICE_INDEPENDENT_REGION_UNION(pci.EFIPY_INDUSTRY_UNION):
    _fields_ = [
        ("Hdr",   pci.PCI_DEVICE_INDEPENDENT_REGION),
        ("Raw",   UINT32 * (sizeof(pci.PCI_DEVICE_INDEPENDENT_REGION) // sizeof(UINT32))),
        ("Raw16", UINT16 * (sizeof(pci.PCI_DEVICE_INDEPENDENT_REGION) // sizeof(UINT16))),
    ]

def print_pci_device(Bus, Dev, Func, PciCfg):
    VendorId                        = PciCfg.Hdr.VendorId
    DeviceId                        = PciCfg.Hdr.DeviceId
    RevisionID                      = PciCfg.Hdr.RevisionID
    Interface, SubClass, BaseClass  = PciCfg.Hdr.ClassCode [:]

    DeviceClass, SubClassDict       = pciids.PciClass.get (BaseClass, (f"Class {BaseClass:02X}", {}))
    SubName, ProgIfDict             =    SubClassDict.get (SubClass,(f"SubClass {BaseClass:02X}", {}))
    ProgIfName                      =    ProgIfDict.get (Interface, f"ProgIf {Interface:02X}")
    VendorName, DeviceDict          = pciids.PciIds.get (VendorId, (f"Vendor {VendorId:04X}", {}))
    DeviceName, _                   =    DeviceDict.get (DeviceId, (f"Device {DeviceId:04X}", {}))

    print (f"{Bus:02X}:{Dev:02X}.{Func:X} {SubName}: {ProgIfName} ({BaseClass:X},{SubClass:X},{Interface:X}): {VendorName}: {DeviceName} ({VendorId:04X} {DeviceId:04X} rev: {RevisionID:02X})")

def scan_single_device(pci_io_ptr, bus, dev, func):
    vid = pci_read16(pci_io_ptr, bus, dev, func, pci.PCI_VENDOR_ID_OFFSET)
    if vid is None or vid in (0x0000, 0xFFFF):
        return None

    pci_cfg = PCI_DEVICE_INDEPENDENT_REGION_UNION()
    for idx in range(0, sizeof(PCI_DEVICE_INDEPENDENT_REGION_UNION), 4):
        val = pci_read32(pci_io_ptr, bus, dev, func, idx)
        if val is None:
            return None
        pci_cfg.Raw[idx // 4] = val

    return pci_cfg

def scan_pci():
    root_bridges = get_all_root_bridges()
    seen_bdfs = set()

    for rb in root_bridges:
        for bus in range(pci.PCI_MAX_BUS + 1):
            # Bus probe: check if this Root Bridge manages the current Bus
            _, status = pci_read(rb, EfiPciWidthUint16, bus, 0, 0, pci.PCI_VENDOR_ID_OFFSET, UINT16)
            if status == 0x8000000000000002:  # EFI_INVALID_PARAMETER
                continue

            for dev in range(pci.PCI_MAX_DEVICE + 1):
                # Read Function 0 first
                dev0 = scan_single_device(rb, bus, dev, 0)
                if not dev0:
                    continue

                bdf_key = (bus, dev, 0)
                if bdf_key not in seen_bdfs:
                    seen_bdfs.add(bdf_key)
                    print_pci_device(bus, dev, 0, dev0)

                # Check if it is a Multifunction Device based on Function 0 HeaderType
                if pci.IS_PCI_MULTI_FUNC(dev0):
                    for func in range(1, pci.PCI_MAX_FUNC + 1):
                        dev_sub = scan_single_device(rb, bus, dev, func)
                        if dev_sub:
                            sub_key = (bus, dev, func)
                            if sub_key not in seen_bdfs:
                                seen_bdfs.add(sub_key)
                                print_pci_device(bus, dev, func, dev_sub)

def main():
    scan_pci()

if __name__ == "__main__":
    main()